  <script src="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/js/bootstrap.bundle.min.js"></script>
  <script src="assets/js/main.js"></script>

  <script>
    document.addEventListener("DOMContentLoaded", function() {
      const baseUrl = window.location.origin + window.location.pathname;

      // QR: load lazily when the collapse is shown (avoids src="" broken-image flash)
      document.querySelectorAll('.collapse').forEach(function(col) {
        col.addEventListener('show.bs.collapse', function() {
          var qrImg = this.querySelector('.dynamic-qr');
          if (qrImg && !qrImg.src) {
            var treeId = qrImg.getAttribute('data-tree');
            qrImg.src = 'https://api.qrserver.com/v1/create-qr-code/?size=150x150&data=' + encodeURIComponent(baseUrl + '?tree=' + treeId);
          }
        });
      });

      // Carousel images: load lazily when the modal is opened, not on page load
      document.querySelectorAll('.modal').forEach(function(modalEl) {
        modalEl.addEventListener('show.bs.modal', function() {
          this.querySelectorAll('img[data-src]').forEach(function(img) {
            img.src = img.getAttribute('data-src');
            img.removeAttribute('data-src');
          });
        });
      });

      // Deep-link: open modal from ?tree=N URL param
      var activeTreeId = new URLSearchParams(window.location.search).get('tree');
      if (activeTreeId) {
        var el = document.getElementById('treeModal' + activeTreeId);
        if (el) new bootstrap.Modal(el).show();
      }

      var thumbs = {
