        6:  'https://sjudata.s3.ap-south-1.amazonaws.com/Trees/SJU+Trees+Image/Mangifera+indica/Mangifera+indica+bark.JPG',
        7:  'https://sjudata.s3.ap-south-1.amazonaws.com/Trees/SJU+Trees+Image/Ficus+racemosa/Ficus+racemosa.jpg',
        8:  'https://sjudata.s3.ap-south-1.amazonaws.com/Trees/SJU+Trees+Image/Melaleuca+citrina/Melaleuca+citrina.jpg',
