      };
      function resizedUrl(url, w, h) {
        return 'https://images.weserv.nl/?url=' + encodeURIComponent(url.replace(/^https?:\/\//, '')) + '&w=' + w + '&h=' + h + '&fit=cover&q=75&output=webp';
      }

      document.querySelectorAll('.tree-item').forEach(function(item, idx) {
        var n = idx + 1;
        var wrap = item.querySelector('.tree-img-wrap');
        var fallback = wrap.querySelector('.tree-img-fallback');
        var img = document.createElement('img');
        img.src = resizedUrl(thumbs[n], 340, 170);
        img.loading = 'lazy';
        img.decoding = 'async';
        img.className = 'tree-thumb-img';
        img.alt = item.querySelector('.tree-name').textContent.trim();
        img.onerror = function() { this.style.display = 'none'; fallback.style.display = 'flex'; };
        img.onload  = function() { fallback.style.display = 'none'; };
        wrap.insertBefore(img, fallback);
      });
    });
  </script>
